package es.nivel36.janus.policy.applicationsettings;
import org.springframework.security.core.Authentication; import org.springframework.stereotype.Component; import es.nivel36.janus.security.ActorResolver;
@Component("applicationSettingsAuthorization") public class ApplicationSettingsAuthorizationAdapter { private final ActorResolver actors; private final ViewApplicationSettingsPolicy view=new ViewApplicationSettingsPolicy(); private final UpdateApplicationSettingsPolicy update=new UpdateApplicationSettingsPolicy(); public ApplicationSettingsAuthorizationAdapter(ActorResolver actors){this.actors=actors;} public boolean canView(Authentication a){return view.allows(actors.resolve(a),null);} public boolean canUpdate(Authentication a){return update.allows(actors.resolve(a),null);} }
